"""One-shot. KBO void signals: read a cancellation on EVERY date.

NOT A REPO FILE. Upload it to the repo root, run it, screenshot the
RESULT line, then delete it:

    python apply_void.py
    rm apply_void.py

WHAT IT WRITES
  * kbo_precompute.py   - the cancellation check no longer sits behind
                          `if gdate < today_str`, plus void_reason and
                          void_risk on every slate row
  * app/views/KBO.py    - both rendered ahead of the measured badge
  * tests/test_kbo_void_signals.py   (new)
  * HANDOFF.md

WHY THIS MATTERS MORE THAN THE ITEM THAT STARTED IT
O1 asked to wire the site's own heat warning back in. Doing that turned
up something worse: parse_week only read a cancellation for games
already in the PAST. Measured on the live page 2026-08-07, mykbostats
listed every KBO game through 08-09 as Canceled during a heat wave, and
the board would have shown all fifteen as scheduled. NPB never had the
bug — it checks <div class="cancel"> with no date gate.

NOTHING HERE WAS TYPED. Every payload was base64-encoded straight from
a verified file, and each target carries the sha256 of the version it
was built FROM. If your tree differs, NOTHING is written and the script
names the file. Re-running is a no-op on files already at target.
"""
import base64
import hashlib
import os
import sys


def sha(path):
    with open(path, "rb") as fh:
        return hashlib.sha256(fh.read()).hexdigest()[:16]


def main():
    drift = []
    for rel, accept, after, *_body in FILES:
        if not os.path.exists(rel):
            if None not in accept:
                drift.append(rel + " (missing)")
            continue
        cur = sha(rel)
        if cur == after:
            continue
        if cur not in accept:
            drift.append(rel + " (unrecognised state " + cur + ")")

    if drift:
        print("ABORT: a file is in a state this script does not know.")
        print("Nothing was written. Send these lines back rather than")
        print("forcing it \u2014 an unrecognised hash means the file changed")
        print("outside this batch, and overwriting would discard that.")
        for d in drift:
            print("  drift:", d)
        print("RESULT: aborted, " + str(len(drift)) + " file(s) drifted")
        return 1

    for rel, _accept, _after, *body in FILES:
        parent = os.path.dirname(rel)
        if parent:
            os.makedirs(parent, exist_ok=True)
        with open(rel, "wb") as fh:
            fh.write(base64.b64decode("".join(body)))

    failures = []
    for rel, _accept, after, *_body in FILES:
        ok = os.path.exists(rel) and sha(rel) == after
        print(("PASS  " if ok else "FAIL  ") + rel)
        if not ok:
            failures.append(rel)

    grep = [
        ("cancellation is read before the past-date gate",
         "kbo_precompute.py", "if POSTPONED_PAT.search(text):", True),
        ("the forward-looking warning is captured",
         "kbo_precompute.py", "VOID_RISK_PAT = re.compile(", True),
        ("the cancellation reason is captured",
         "kbo_precompute.py", "CANCEL_REASON_PAT = re.compile(", True),
        ("both ship on the slate row",
         "kbo_precompute.py", '"void_risk": g.get("void_risk")', True),
        ("a postponed game cannot also be final",
         "kbo_precompute.py",
         'FINAL_PAT.search(text) and g["status"] != "postponed"', True),
        ("the board renders the reason",
         "app/views/KBO.py", 'g.get("void_reason")', True),
        ("the board renders the risk",
         "app/views/KBO.py", 'g.get("void_risk")', True),
    ]
    for label, rel, needle, want in grep:
        try:
            text = open(rel, encoding="utf-8").read()
        except OSError:
            ok = False
        else:
            ok = (needle in text) if want else (needle not in text)
        print(("PASS  " if ok else "FAIL  ") + label)
        if not ok:
            failures.append(label)

    print("RESULT:", "all checks passed" if not failures
          else "FAILED " + "; ".join(failures))
    return 1 if failures else 0


